<?php
declare(strict_types=1);namespace QualitySystem\Tests;use PHPUnit\Framework\TestCase;
final class ProgramPloCloMatrixTest extends TestCase{public function testMatrixEndpointUsesAuthenticationCsrfAndProgramScope():void{$s=file_get_contents(dirname(__DIR__).'/program_plo_clo_matrix.php');$this->assertStringContainsString("require_once __DIR__.'/auth_check.php'",$s);$this->assertStringContainsString('findScoped',$s);$this->assertStringContainsString('csrfField()',$s);$this->assertStringContainsString("'programs','manage'",$s);}public function testMatrixDoesNotInventMissingClos():void{$s=file_get_contents(dirname(__DIR__).'/program_plo_clo_matrix.php');$this->assertStringContainsString('No approved CLOs are recorded yet.',$s);$this->assertStringContainsString('Official CLO text',$s);}public function testCsvExportContainsPloColumns():void{$s=file_get_contents(dirname(__DIR__).'/program_plo_clo_matrix.php');$this->assertStringContainsString('plo-clo-matrix.csv',$s);$this->assertStringContainsString("array_column(\$plos,'plo_code')",$s);}public function testRequestedAlignmentLegendIsUsed():void{$s=file_get_contents(dirname(__DIR__).'/program_plo_clo_matrix.php');$this->assertStringContainsString('P = Practical; I = Introductory; M = Mastery.',$s);$this->assertStringContainsString("['Practical','Introductory','Mastery']",$s);$this->assertStringNotContainsString('Primary alignment',$s);}}
